import { Injectable, signal } from '@angular/core';

export interface AppMessage {
  id: number;
  style: 'success' | 'error';
  text: string;
}

/** Success/error messages shown by the shell (replaces widget/message). */
@Injectable({ providedIn: 'root' })
export class MessageService {
  readonly messages = signal<AppMessage[]>([]);
  private nextId = 1;

  success(text: string): void {
    this.add('success', text);
  }

  error(text: string): void {
    this.add('error', text);
  }

  dismiss(id: number): void {
    this.messages.update((list) => list.filter((m) => m.id !== id));
  }

  private add(style: AppMessage['style'], text: string): void {
    const id = this.nextId++;
    this.messages.update((list) => [...list, { id, style, text }]);
    // Same 5 second close delay as the GWT message widget.
    setTimeout(() => this.dismiss(id), 5000);
  }
}

