          <a routerLink="/rating">Ratings</a>
          <a routerLink="/report">Reports</a>
        </div>
      </div>
    </div>

    <div class="messages">
      @for (m of messageService.messages(); track m.id) {
        <div [attr.id]="m.style === 'success' ? 'gwt-debug-successMessage' : 'gwt-debug-errorMessage'"
             [class]="'message ' + m.style">
