import json, time, urllib.request
BASE = "http://localhost:8888/ng/"
DRV = "http://localhost:9515"
def req(method, path, body=None):
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(DRV + path, data=data, method=method, headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(r) as f:
        return json.loads(f.read())["value"]
sid = req("POST", "/session", {"capabilities": {"alwaysMatch": {"goog:chromeOptions": {
    "binary": "/usr/bin/chromium", "args": ["--headless=new", "--no-sandbox", "--disable-gpu", "--window-size=1280,1000"]}}}})
S = f"/session/{sid}"
def find(sel, by="css selector", el=None):
    base = f"{S}/element" if el is None else f"{S}/element/{el}/element"
    return req("POST", base, {"using": by, "value": sel})
def find_all(sel, el=None):
    base = f"{S}/elements" if el is None else f"{S}/element/{el}/elements"
    return [list(x.values())[0] for x in req("POST", base, {"using": "css selector", "value": sel})]
def wait(fn, msg, t=10):
    end = time.time() + t
    while time.time() < end:
        try:
            v = fn()
            if v: return v
        except Exception: pass
        time.sleep(0.2)
    raise AssertionError("timeout: " + msg)
def by_id(i): return wait(lambda: find("#gwt-debug-" + i)[list(find("#gwt-debug-" + i).keys())[0]] if False else find_id(i), i)
def find_id(i):
    try:
        r = req("POST", f"{S}/element", {"using": "css selector", "value": "#gwt-debug-" + i})
        return list(r.values())[0]
    except Exception: return None
def text(el): return req("GET", f"{S}/element/{el}/text")
def click(el): req("POST", f"{S}/element/{el}/click", {})
def clear_send(el, keys):
    req("POST", f"{S}/element/{el}/clear", {}); req("POST", f"{S}/element/{el}/value", {"text": keys})
def rows(tid):
    t = by_id(tid)
    return find_all("tbody:first-of-type tr", t) if False else find_all("tbody tr", t)
def cells(row): return [text(c) for c in find_all("td", row)]
def headers(tid): return [text(h) for h in find_all("thead th", by_id(tid))]
def col(tid, name):
    return headers(tid).index(name)
def cell(tid, row_i, name):
    return text(find_all("td", rows(tid)[row_i])[col(tid, name)])
def row_count(tid): return len(rows(tid))
def confirm_ok():
    req("POST", f"{S}/execute/sync", {"script": "window.confirm = function(){return true;};", "args": []})
def success_text():
    m = wait(lambda: find_id("successMessage"), "success message")
    return text(find_all("span", m)[0])
def wait_gone(el): wait(lambda: req("GET", f"{S}/element/{el}/displayed") is False or False, "gone") 
def wait_detached(el):
    def f():
        try:
            req("GET", f"{S}/element/{el}/text"); return False
        except Exception: return True
    wait(f, "detached")
results = []
def scenario(name, fn):
    try:
        fn(); results.append((name, "PASS"))
    except Exception as e:
        results.append((name, "FAIL: " + str(e)))

def nav(tok):
    req("POST", f"{S}/url", {"url": BASE + "#/" + tok})
    time.sleep(1.0)

# Manufacturers
nav("manufacturer")
def m_editor():
    click(by_id("create-manufacturer"))
    assert wait(lambda: by_id("manufacturer-editor"), "editor")
scenario("M: create shows editor", m_editor)
def m_close():
    n = row_count("manufacturers")
    click(by_id("create-manufacturer")); time.sleep(0.5)
    clear_send(by_id("manufacturer-input"), "Ford")
    click(by_id("manufacturer-close")); time.sleep(0.5)
    assert row_count("manufacturers") == n
scenario("M: close keeps table", m_close)
def m_save():
    n = row_count("manufacturers")
    click(by_id("create-manufacturer")); time.sleep(0.5)
    clear_send(by_id("manufacturer-input"), "Plymouth")
    click(by_id("manufacturer-save"))
    assert "saved" in success_text()
    time.sleep(0.5)
    assert row_count("manufacturers") == n + 1, "row count"
    assert cell("manufacturers", row_count("manufacturers") - 1, "Name") == "Plymouth", "last row"
scenario("M: save creates row", m_save)
def m_edit():
    click(find_all("tbody tr td:nth-last-child(2) button", by_id("manufacturers"))[0])
    time.sleep(0.5)
    clear_send(by_id("manufacturer-input"), "Ford")
    click(by_id("manufacturer-save"))
    assert "saved" in success_text()
    time.sleep(0.5)
    assert cell("manufacturers", 0, "Name") == "Ford", "first row"
scenario("M: edit first", m_edit)
def m_delete():
    n = row_count("manufacturers")
    confirm_ok()
    click(find_all("tbody tr td:last-child button", by_id("manufacturers"))[0])
    time.sleep(1)
    assert row_count("manufacturers") == n - 1
scenario("M: delete first", m_delete)

# Ratings
nav("rating")
def r_add():
    n = row_count("ratings")
    click(by_id("ratingCreate")); time.sleep(0.5)
    clear_send(by_id("ratingInput"), "10")
    click(by_id("ratingSave"))
    assert "saved" in success_text()
    time.sleep(0.5)
    assert row_count("ratings") == n + 1
scenario("R: add rating", r_add)
def r_delete():
    n = row_count("ratings")
    confirm_ok()
    click(find_all("tbody tr td:last-child button", by_id("ratings"))[0])
    time.sleep(1)
    assert row_count("ratings") == n - 1
scenario("R: delete first", r_delete)

# Reports
nav("rating")
avg = {}
for i in range(row_count("ratings")):
    car = cell("ratings", i, "Car"); r = float(cell("ratings", i, "Rating"))
    m = car.split("/")[0]; avg.setdefault(m, []).append(r)
nav("report")
def rep():
    t = by_id("reports")
    got = {}
    for i in range(len(rows("reports"))):
        got[cell("reports", i, "Manufacturer")] = float(cell("reports", i, "Rating"))
    for m, rs in avg.items():
        assert abs(got[m] - sum(rs) / len(rs)) < 0.001, m
scenario("Rep: averages", rep)

for n, r in results: print(n, "->", r)
req("DELETE", S)
