package com.gwtplatform.carstore.cucumber.harness;

import static org.junit.Assert.assertTrue;

import com.gwtplatform.carstore.cucumber.application.widgets.HeaderWidgetPage;
import com.gwtplatform.carstore.cucumber.application.widgets.MessageWidgetPage;
import cucumber.api.java.Before;
import cucumber.api.java.en.Given;
import cucumber.api.java.en.Then;
import cucumber.runtime.java.guice.ScenarioScoped;
import javax.inject.Inject;
import org.openqa.selenium.WebDriver;

/** Glue for the Background and message steps that the e2e step files do not define. */
@ScenarioScoped
public class HarnessSteps {
    private static final String APP_URL = "http://localhost:8888/ng/";

    private final WebDriver webDriver;
    private final HeaderWidgetPage headerPage;
    private final MessageWidgetPage messageWidgetPage;

    @Inject
    HarnessSteps(WebDriver webDriver, HeaderWidgetPage headerPage, MessageWidgetPage messageWidgetPage) {
        this.webDriver = webDriver;
        this.headerPage = headerPage;
        this.messageWidgetPage = messageWidgetPage;
    }

    @Before
    public void openApp() {
        webDriver.get(APP_URL);
    }

    @Given("^I'm logged in$")
    public void imLoggedIn() {
        // The REST API is not protected, so there is no login step.
    }

    @Given("^I navigate to the manufacturer page$")
    public void navigateToManufacturers() {
        headerPage.navigateTo("manufacturer");
    }

    @Given("^I navigate to the rating page$")
    public void navigateToRatings() {
        headerPage.navigateTo("rating");
    }

    @Given("^I navigate to the report page$")
    public void navigateToReports() {
        headerPage.navigateTo("report");
    }

    @Then("^I see a success message containing (\\S+)$")
    public void iSeeSuccessMessageContaining(String message) {
        assertTrue(messageWidgetPage.hasSuccessMessage(message));
    }
}
